from pathlib import Path
import re

p=Path('index.html')
s=p.read_text()

stages={
'Normal physiology':'''<section class="lesson-stage" data-step-name="Normal physiology"><span class="stage-label">03 · Fundamental knowledge</span><h2>What does insulin<br><i>actually do?</i></h2><p class="stage-lead">Before DKA makes sense, insulin has to mean more than “a hormone that lowers glucose”. It is the body's signal that fuel is available.</p><div class="system-map"><div class="map-node"><span>Pancreas</span><strong>Glucose rises → β cells release insulin</strong><p>Insulin signals the fed state.</p></div><div class="map-arrow">→</div><div class="map-node"><span>Whole body</span><strong>Use and store fuel</strong><p>Muscle takes up glucose; liver stores rather than produces it.</p></div><div class="map-arrow">→</div><div class="map-node"><span>Adipose</span><strong>Stop mobilising fat</strong><p>Insulin restrains lipolysis and therefore ketone production.</p></div></div><div class="normal-actions"><div><span>01</span><h3>Muscle</h3><p>Insulin promotes GLUT4-mediated glucose uptake and glycogen synthesis.</p></div><div><span>02</span><h3>Liver</h3><p>Insulin suppresses glycogenolysis and gluconeogenesis and favours glycogen formation.</p></div><div><span>03</span><h3>Adipose tissue</h3><p>Insulin suppresses hormone-sensitive lipase, limiting release of free fatty acids.</p></div></div><div class="mechanism-note"><b>Take home:</b> insulin is a signal of energy abundance. Its absence makes the body behave metabolically as though it is starving, even while glucose is accumulating in the blood.</div></section>''',
'The disruption':'''<section class="lesson-stage" data-step-name="The disruption"><span class="stage-label">04 · Remove insulin</span><h2>One failure<br><i>two pathways</i></h2><p class="stage-lead">Absolute insulin deficiency plus relatively unopposed counter-regulatory hormones creates the two processes that define DKA.</p><div class="fault-tree"><div class="fault-root"><span>CENTRAL FAILURE</span><strong>Absolute insulin deficiency</strong></div><div class="fault-branches"><div class="fault-branch"><h3>Glucose → volume pathway</h3><div class="chain"><span>↓ peripheral glucose utilisation</span><span>↑ hepatic glycogenolysis + gluconeogenesis</span><span>Hyperglycaemia</span><span>Filtered glucose exceeds renal reabsorptive capacity</span><span>Glycosuria → osmotic diuresis</span><span>Water + electrolyte depletion</span></div></div><div class="fault-branch"><h3>Fat → acid pathway</h3><div class="chain"><span>Loss of insulin restraint on hormone-sensitive lipase</span><span>Lipolysis → free fatty acids</span><span>Hepatic β-oxidation → acetyl-CoA</span><span>Acetoacetate + β-hydroxybutyrate</span><span>Bicarbonate buffering consumed</span><span>High-anion-gap metabolic acidosis</span></div></div></div></div><div class="mechanism-note"><b>Take home:</b> DKA is not simply severe hyperglycaemia. Hyperglycaemia drives volume loss; uncontrolled ketogenesis drives the acidosis.</div></section>''',
'Symptoms':'''<section class="lesson-stage" data-step-name="Symptoms" data-requires-answer><span class="stage-label">05 · Derive the symptoms</span><h2>Why does Maya<br><i>feel like this?</i></h2><p class="stage-lead">Do not memorise the symptom list. Predict each symptom from the mechanism.</p><div class="question-card mcq" data-question="symptoms"><h3>Mechanism question</h3><p>Why does hyperglycaemia produce both polyuria and intense thirst?</p><div class="mcq-options"><button class="mcq-option" data-correct="false" data-feedback="The defining process is not primary ADH failure. The water loss starts with glucose remaining in tubular fluid."><b>A</b><span>Hyperglycaemia directly switches off ADH</span></button><button class="mcq-option" data-correct="true" data-feedback="When filtered glucose exceeds renal reabsorptive capacity, glucose remains in tubular fluid and retains water osmotically. The resulting water loss and hypertonicity/volume depletion stimulate thirst."><b>B</b><span>Glycosuria causes osmotic diuresis; water loss then drives thirst</span></button><button class="mcq-option" data-correct="false" data-feedback="Aldosterone suppression is not the central mechanism of DKA polyuria."><b>C</b><span>Insulin deficiency causes a primary salt diuresis</span></button><button class="mcq-option" data-correct="false" data-feedback="Kussmaul breathing contributes to insensible loss but cannot explain weeks of marked polyuria."><b>D</b><span>Hyperventilation is the main source of water loss</span></button></div><div class="question-feedback" aria-live="polite"></div></div><div class="normal-actions"><div><span>WHY?</span><h3>Weight loss</h3><p>Water and urinary calorie loss combine with a catabolic state: lipolysis and proteolysis continue despite extracellular glucose abundance.</p></div><div><span>WHY?</span><h3>Vomiting</h3><p>Ketosis, acidaemia, dehydration and disturbed gastrointestinal function contribute. DKA can mimic an acute abdomen.</p></div><div><span>WHY?</span><h3>Abdominal pain</h3><p>Often accompanies significant ketoacidosis; persistence after metabolic improvement should make you reconsider another abdominal diagnosis.</p></div></div><div class="mechanism-note"><b>Take home:</b> the symptoms are visible outputs of the metabolic pathways, not unrelated diagnostic clues.</div></section>''',
'Signs':'''<section class="lesson-stage" data-step-name="Signs" data-requires-answer><span class="stage-label">06 · Derive the signs</span><h2>The lungs are<br><i>trying to help</i></h2><p class="stage-lead">Deep breathing is not primarily a respiratory disease. It is a compensatory response to metabolic acidosis.</p><div class="question-card mcq" data-question="signs"><h3>Mechanism question</h3><p>Why does metabolic acidosis produce Kussmaul breathing?</p><div class="mcq-options"><button class="mcq-option" data-correct="false" data-feedback="Anxiety can alter breathing, but it does not explain the organised compensatory response to acidaemia."><b>A</b><span>Anxiety stimulates respiratory drive</span></button><button class="mcq-option" data-correct="true" data-feedback="Acidaemia increases ventilatory drive. Greater alveolar ventilation lowers PaCO₂; through the bicarbonate buffer relationship this partially defends pH, although the lungs cannot remove the ketoacids themselves."><b>B</b><span>Increased ventilation lowers CO₂ and partially compensates for metabolic acidosis</span></button><button class="mcq-option" data-correct="false" data-feedback="Pulmonary oedema is not the mechanism of characteristic Kussmaul respiration."><b>C</b><span>Pulmonary oedema causes hypoxaemia</span></button><button class="mcq-option" data-correct="false" data-feedback="Respiratory muscle weakness would impair ventilation rather than create this deep compensatory pattern."><b>D</b><span>Respiratory muscles are weakened by insulin deficiency</span></button></div><div class="question-feedback" aria-live="polite"></div></div><div class="mechanism-note"><b>Acid–base link:</b> ketoacids consume bicarbonate → pH falls → chemoreceptor-driven ventilation rises → PaCO₂ falls → pH is partially defended. Tachycardia, meanwhile, is an expected compensatory response to reduced effective circulating volume.</div></section>''',
'Investigations':'''<section class="lesson-stage" data-step-name="Investigations" data-requires-answer><span class="stage-label">07 · Test a physiological question</span><h2>Why order<br><i>each test?</i></h2><p class="stage-lead">Investigations are useful when you know which part of the mechanism each one is measuring.</p><div class="result-table"><div class="result"><span>Is glucose regulation failing?</span><strong>Glucose 28.4</strong><small>Measures hyperglycaemia, but glucose alone does not define the severity of ketoacidosis.</small></div><div class="result"><span>Is fat metabolism uncontrolled?</span><strong>β-OHB 5.6</strong><small>Blood ketones tell us whether clinically important ketogenesis is active.</small></div><div class="result"><span>Has ketogenesis caused acidosis?</span><strong>Venous pH 7.12</strong><small>Venous gas assesses acid-base severity; routine arterial sampling is usually unnecessary for this question.</small></div><div class="result"><span>What happened to buffer?</span><strong>HCO₃⁻ 9</strong><small>Bicarbonate falls as ketoacid hydrogen ions are buffered.</small></div><div class="result"><span>What about potassium?</span><strong>K⁺ 4.7</strong><small>A normal serum concentration can conceal major total-body depletion.</small></div><div class="result"><span>Water + sodium relationship?</span><strong>Na⁺ 132</strong><small>Interpret sodium in the context of hyperglycaemia, water shifts and changing effective osmolality.</small></div></div><div class="question-card mcq" data-question="investigations"><h3>The potassium trap</h3><p>Serum potassium is 4.7 mmol/L. What does that tell you about total-body potassium?</p><div class="mcq-options"><button class="mcq-option" data-correct="false" data-feedback="Serum concentration is only one compartment and does not measure whole-body stores."><b>A</b><span>Total-body potassium must be normal</span></button><button class="mcq-option" data-correct="true" data-feedback="Osmotic diuresis causes substantial potassium loss. Insulin deficiency, hyperosmolality and acidaemia favour extracellular redistribution, so serum potassium may look normal or high despite depletion."><b>B</b><span>Total-body potassium is likely depleted despite the serum value</span></button><button class="mcq-option" data-correct="false" data-feedback="This result alone does not demonstrate renal potassium retention."><b>C</b><span>The kidneys must be retaining potassium</span></button><button class="mcq-option" data-correct="false" data-feedback="Potassium becomes especially important once insulin drives it intracellularly."><b>D</b><span>Potassium can be ignored until glucose normalises</span></button></div><div class="question-feedback" aria-live="polite"></div></div><div class="mechanism-note"><b>Take home:</b> glucose measures one branch, ketones another, and pH/bicarbonate their acid-base consequence. Electrolytes and renal indices tell you what osmotic diuresis and treatment may do next. Imaging is not routine in uncomplicated DKA.</div></section>''',
'Treatment':'''<section class="lesson-stage" data-step-name="Treatment" data-requires-answer><span class="stage-label">08 · Repair the physiology</span><h2>Treatment should<br><i>feel inevitable</i></h2><p class="stage-lead">Once you understand what is broken, each intervention has a precise physiological job.</p><div class="question-card mcq" data-question="treatment"><h3>Key concept</h3><p>Glucose has fallen substantially but ketones and acidosis persist. Why might dextrose be added while insulin continues?</p><div class="mcq-options"><button class="mcq-option" data-correct="true" data-feedback="Insulin is needed until ketogenesis is suppressed and ketoacidosis resolves. Dextrose can prevent hypoglycaemia while allowing that insulin to continue."><b>A</b><span>To permit ongoing insulin until ketogenesis and acidosis resolve</span></button><button class="mcq-option" data-correct="false" data-feedback="Dextrose is not given to stimulate ketone production."><b>B</b><span>To increase ketone production for renal clearance</span></button><button class="mcq-option" data-correct="false" data-feedback="A falling glucose does not mean the ketoacidosis has resolved."><b>C</b><span>Because insulin should stop as soon as glucose falls</span></button><button class="mcq-option" data-correct="false" data-feedback="The purpose is metabolic control, not correction of a laboratory artefact."><b>D</b><span>To correct falsely low bedside glucose readings</span></button></div><div class="question-feedback" aria-live="polite"></div></div><div class="treatment-grid"><div class="treatment-card"><span>01 · FLUID</span><h3>Restore effective circulation</h3><p>Replace intravascular/extracellular losses, support perfusion and renal function, and calculate ongoing replacement using the current paediatric pathway.</p></div><div class="treatment-card"><span>02 · INSULIN</span><h3>Stop ketogenesis</h3><p>Insulin suppresses lipolysis and hepatic ketone production. Current UK paediatric guidance uses continuous IV insulin after initial fluid therapy and no IV insulin bolus.</p></div><div class="treatment-card"><span>03 · POTASSIUM</span><h3>Expect the serum level to fall</h3><p>Total-body stores are depleted. Insulin and metabolic recovery move potassium intracellularly, so replacement and serial monitoring are integral to treatment.</p></div><div class="treatment-card"><span>04 · DEXTROSE</span><h3>Keep insulin going safely</h3><p>When glucose falls before ketoacidosis has resolved, dextrose allows continued insulin without causing hypoglycaemia.</p></div></div><div class="safety-strip"><b>SAFETY</b><p>Use the current BSPED/local paediatric DKA pathway for exact fluids, insulin, potassium and monitoring. Neurological deterioration requires urgent senior assessment and treatment; cerebral injury in DKA is multifactorial and should not be reduced to the simplistic idea that “fluids cause cerebral oedema”.</p></div></section>''',
'Transfer case':'''<section class="lesson-stage" data-step-name="Transfer case" data-requires-answer><span class="stage-label">09 · Prove you understand it</span><h2>Don't chase<br><i>the glucose</i></h2><p class="stage-lead">A seven-year-old with type 1 diabetes has a pump interruption. She is vomiting and breathing deeply. Glucose 14.2 mmol/L, blood ketones 4.8 mmol/L, venous pH 7.19.</p><div class="question-card mcq" data-question="transfer"><h3>Transfer question</h3><p>Why is the relatively modest glucose falsely reassuring?</p><div class="mcq-options"><button class="mcq-option" data-correct="false" data-feedback="DKA is not defined by an extreme glucose threshold alone."><b>A</b><span>DKA requires glucose above 25 mmol/L</span></button><button class="mcq-option" data-correct="true" data-feedback="The dangerous metabolic process is demonstrated by active ketogenesis plus metabolic acidosis. Glucose is only one component of the physiology."><b>B</b><span>Ketonaemia plus acidosis shows that insulin-deficient ketogenesis is active</span></button><button class="mcq-option" data-correct="false" data-feedback="Vomiting is important but nonspecific."><b>C</b><span>Vomiting alone proves DKA</span></button><button class="mcq-option" data-correct="false" data-feedback="Pump interruption is a precipitant; the biochemical abnormalities demonstrate the metabolic consequence."><b>D</b><span>Pump interruption alone defines DKA</span></button></div><div class="question-feedback" aria-live="polite"></div></div><div class="mechanism-note"><b>Transfer principle:</b> ask whether insulin deficiency is driving ketogenesis and whether that ketogenesis has produced acidosis. This protects you from equating “DKA severity” with the glucose number.</div></section>''',
'Explain it back':'''<section class="lesson-stage" data-step-name="Explain it back"><span class="stage-label">10 · Retrieval and synthesis</span><h2>Explain DKA<br><i>without a list</i></h2><p class="stage-lead">Explain Maya in a causal chain: normal insulin action → what failed → why each symptom/sign appeared → why each test was chosen → why each treatment works.</p><div class="explain-card"><h3>Your 60-second explanation</h3><textarea aria-label="Write your explanation of DKA" placeholder="Without insulin, the body behaves as though it is starving because…"></textarea><button class="model-toggle">Show model explanation</button><div class="model-answer"><b>One possible explanation:</b><br>Absolute insulin deficiency removes the fed-state signal. Peripheral glucose utilisation falls while hepatic glucose production continues, producing hyperglycaemia. Glycosuria then causes osmotic diuresis, water/electrolyte loss, polyuria, thirst, dehydration and compensatory tachycardia. Simultaneously, loss of insulin restraint on lipolysis delivers free fatty acids to the liver, generating ketones and metabolic acidosis; deep Kussmaul ventilation lowers CO₂ to partially defend pH. We therefore measure glucose, ketones and venous acid-base status to identify the two metabolic branches and their consequence, and electrolytes/renal indices to understand losses and treatment risk. Fluids restore circulation, insulin stops lipolysis and ketogenesis, potassium is anticipated because whole-body stores are depleted, and dextrose may be added so insulin can continue until ketoacidosis resolves.</div></div><div class="mechanism-note"><b>Five take-homes:</b> DKA is insulin deficiency, not simply high glucose. Hyperglycaemia explains osmotic diuresis; lipolysis explains ketones and acidosis. Serum potassium does not equal body potassium stores. Insulin treats ketogenesis as well as glucose. Treatment is the physiology run in reverse.</div><div class="source-list"><b>Clinical grounding:</b> Exact management must follow the current <a href="https://www.bsped.org.uk/clinical-resources/bsped-dka-guidelines/" target="_blank" rel="noopener">BSPED paediatric DKA guideline</a>, <a href="https://www.nice.org.uk/guidance/ng18/chapter/1-recommendations" target="_blank" rel="noopener">NICE NG18</a> and the local paediatric pathway. Educational content only.</div></section>'''
}

for name,new in stages.items():
    pat=rf'<section class="lesson-stage"(?=[^>]*data-step-name="{re.escape(name)}")[\s\S]*?</section>'
    s2,n=re.subn(pat,new,s,count=1)
    if n!=1:
        raise SystemExit(f'Could not replace stage: {name} ({n})')
    s=s2

p.write_text(s)
print('Rewrote DKA lesson stages 03-10')
